import hashlib
import hmac
import json

from payhook.errors import InvalidNotification


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    # --- timestamp ---
    ts_str = headers.get("X-Pay-Timestamp")
    if not ts_str:
        raise InvalidNotification("Missing timestamp")
    try:
        ts = float(ts_str)
    except (ValueError, TypeError):
        raise InvalidNotification("Malformed timestamp")

    if abs(now - ts) > 300:
        raise InvalidNotification("Stale delivery")

    # --- parse body ---
    try:
        payload = json.loads(raw_body)
    except (json.JSONDecodeError, ValueError):
        raise InvalidNotification("Malformed JSON")

    if not isinstance(payload, dict):
        raise InvalidNotification("Invalid payload type")

    # --- required fields ---
    event_id = payload.get("event_id")
    account_id = payload.get("account_id")
    amount_minor = payload.get("amount_minor")
    currency = payload.get("currency")

    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("Missing or invalid event_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("Missing or invalid account_id")
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int) or amount_minor < 0:
        raise InvalidNotification("Missing or invalid amount_minor")
    if (not isinstance(currency, str) or len(currency) != 3
            or not currency.isascii() or not currency.isupper()):
        raise InvalidNotification("Missing or invalid currency")

    result = {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }

    # --- v1 signature (current path) ---
    sig = headers.get("X-Pay-Signature", "")
    if sig.startswith("v1="):
        expected = hmac.new(
            secret, ts_str.encode("ascii") + b"." + raw_body, hashlib.sha256
        ).hexdigest()
        if hmac.compare_digest(expected, sig[3:]):
            return result

    # --- r0 receipt (legacy migration path) ---
    receipt = headers.get("X-Pay-Receipt", "")
    if receipt.startswith("r0="):
        r0_digest = hmac.new(
            secret,
            ts_str.encode("ascii") + b"." + event_id.encode("utf-8"),
            hashlib.sha256,
        ).hexdigest()
        if hmac.compare_digest(r0_digest, receipt[3:]):
            return result

    raise InvalidNotification("Invalid or missing signature")
